"""Hand-written rows for topic `rules`: non-template Khmer narrative. Every result is checked by SymPy strings."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "lib"))
from common import *

H = []
# domain sentence for a row whose function holds a root, keyed by a piece of the problem
HD = {"$f(x)=\\sqrt{x}$ គឺ": "ដែនកំណត់ $D=[0;+\\infty)$ ហើយយើងសិក្សាដេរីវេចំពោះ $x>0$ ។",
      "\\sqrt{x+1}+\\sqrt{x}": "ដែនកំណត់ $D=(0;+\\infty)$ ។",
      "ដោយប្រើដេរីវេនៃ $f(x)=\\sqrt{x}$": "ដែនកំណត់ $D=[0;+\\infty)$ ហើយ $f$ មានដេរីវេត្រង់ $x=100$ ។",
      "ជាអនុគមន៍វិជ្ជមាន": "ដោយ $u>0$ កន្សោមមានន័យលើដែនកំណត់ $D$ របស់ $u$ ។",
      "$f\\circ g$ និង $g\\circ f$": "ដែនកំណត់នៃ $f\\circ g$ គឺ $D=[0;+\\infty)$ ហើយដែនកំណត់នៃ $g\\circ f$ គឺ $D=IR$ ។",
      "\\sqrt{x}\\left(x^2-\\frac{1}{x}\\right)": "ដែនកំណត់ $D=(0;+\\infty)$ ។",
      "\\sqrt{x}+\\sqrt{y}=3": "ទំនាក់ទំនងមានន័យលើ $D=(0;+\\infty)$ ព្រោះ $x,y>0$ ។"}
def row(sub, diff, prob, sol, ans, checks):
    for frag, line in HD.items():
        if frag in prob:
            sol = line + "\n" + sol
            break
    H.append(make_row("rules", sub, diff, prob, sol, ans, [check(*c) for c in checks], "rules_hand"))

row("definition_general", "medium",
 "ចូរស្រាយបញ្ជាក់ដោយប្រើនិយមន័យថា បើ $f(x)=x^2$ នោះ $f'(x)=2x$ ចំពោះគ្រប់ចំនួនពិត $x$ ។",
 "យកចំនួនពិត $x$ មួយ ហើយពិនិត្យផលធៀបកំណើនត្រង់ $x$ ៖\n$$\\frac{f(x+h)-f(x)}{h}=\\frac{(x+h)^2-x^2}{h}=\\frac{2xh+h^2}{h}=2x+h$$\nការសម្រួលនេះត្រឹមត្រូវ ព្រោះ $h\\neq0$ ។ ពេល $h$ ខិតជិតសូន្យ កន្សោម $2x+h$ ខិតជិត $2x$ ។\nដូចនេះ $\\boxed{f'(x)=2x}$ ។",
 "f'(x)=2x", [("limit(((x+h)**2-x**2)/h,h,0)", "2*x", "definition")])
