row("chain_two_ways", "medium",
 "គណនាដេរីវេនៃ $f(x)=(2x+1)^3$ ជាពីររបៀប ៖ ប្រើរូបមន្តអនុគមន៍បណ្ដាក់ និងពន្លាតទ្វេធា ។",
 "របៀបទី១ ៖ យក $u=2x+1$ នោះ $u'=2$ ហើយ $$f'(x)=3\\cdot2\\cdot(2x+1)^2=6(2x+1)^2$$\nរបៀបទី២ ៖ ពន្លាតសិន $f(x)=8x^3+12x^2+6x+1$ រួចធ្វើដេរីវេ ៖ $$f'(x)=24x^2+24x+6=6(4x^2+4x+1)=6(2x+1)^2$$\nចម្លើយទាំងពីរត្រូវគ្នា ប៉ុន្តែរបៀបទី១ខ្លីជាង ។\nដូចនេះ $\\boxed{f'(x)=6(2x+1)^2}$ ។",
 "f'(x)=6(2x+1)^2", [("diff((2*x+1)**3,x)", "6*(2*x+1)**2", "derivative")])
row("chain_of_quotient", "hard",
 "គេឱ្យ $f(x)=\\sqrt{\\frac{1+x}{1-x}}$ ។ រកដែនកំណត់ រួចបង្ហាញថា $f'(x)=\\frac{1}{(1-x)^2f(x)}$ ។",
 "កន្សោមក្រោមឫសត្រូវមិនអវិជ្ជមាន ហើយភាគបែងខុសពីសូន្យ ។ សញ្ញានៃផលចែកឱ្យ $D=[-1;1)$ ។\nតាង $w=\\frac{1+x}{1-x}$ ។ រូបមន្តផលចែកឱ្យ $$w'=\\frac{(1-x)+(1+x)}{(1-x)^2}=\\frac{2}{(1-x)^2}$$\nចំពោះ $-1<x<1$ យើងមាន $f=\\sqrt{w}$ ដូច្នេះ $$f'(x)=\\frac{w'}{2\\sqrt{w}}=\\frac{2}{(1-x)^2}\\cdot\\frac{1}{2f(x)}$$\nដូចនេះ $\\boxed{f'(x)=\\frac{1}{(1-x)^2f(x)}}$ ។",
 "f'(x)=\\frac{1}{(1-x)^2f(x)}", [("subs(diff(sqrt((1+x)/(1-x)),x),x,Rational(1,2))", "4/sqrt(3)", "at 1/2"), ("subs(1/((1-x)**2*sqrt((1+x)/(1-x))),x,Rational(1,2))", "4/sqrt(3)", "formula at 1/2")])
row("rationalize_first", "hard",
 "គេឱ្យ $f(x)=\\frac{1}{\\sqrt{x+1}+\\sqrt{x}}$ ចំពោះ $x>0$ ។ សម្រួលកន្សោម $f(x)$ រួចគណនា $f'(x)$ ។",
 "បើប្រើរូបមន្តផលចែកភ្លាម ការគណនានឹងវែង ។ យើងគុណនឹងកន្សោមឆ្លាស់ជាមុនសិន ៖\n$$f(x)=\\frac{\\sqrt{x+1}-\\sqrt{x}}{(x+1)-x}=\\sqrt{x+1}-\\sqrt{x}$$\nឥឡូវវាជាផលដកនៃឫសពីរ ។ តាម $(\\sqrt{u})'=\\frac{u'}{2\\sqrt{u}}$ ៖\n$$f'(x)=\\frac{1}{2\\sqrt{x+1}}-\\frac{1}{2\\sqrt{x}}$$\nដូចនេះ $\\boxed{f'(x)=\\frac{1}{2\\sqrt{x+1}}-\\frac{1}{2\\sqrt{x}}}$ ។",
 "f'(x)=\\frac{1}{2\\sqrt{x+1}}-\\frac{1}{2\\sqrt{x}}", [("diff(1/(sqrt(x+1)+sqrt(x)),x)", "1/(2*sqrt(x+1))-1/(2*sqrt(x))", "derivative")])
row("nth_derivative", "hard",
 "គេឱ្យ $f(x)=\\frac{1}{x}$ ។ គណនា $f'(x)$ , $f''(x)$ , $f'''(x)$ រួចស្មានរូបមន្តនៃដេរីវេលំដាប់ $n$ ហើយស្រាយបញ្ជាក់ដោយកំណើន ។",
 "សរសេរ $f(x)=x^{-1}$ ហើយធ្វើដេរីវេម្ដងមួយៗ ៖\n$$f'(x)=-x^{-2},\\quad f''(x)=2x^{-3},\\quad f'''(x)=-6x^{-4}$$\nលំនាំបង្ហាញថា សញ្ញាឆ្លាស់គ្នា ហើយមេគុណជាហ្វាក់តូរីយែល ។ យើងស្មាន $$f^{(n)}(x)=\\frac{(-1)^nn!}{x^{n+1}}$$\nចំពោះ $n=1$ រូបមន្តពិត ។ សន្មតថាវាពិតចំពោះ $n$ ។ ធ្វើដេរីវេម្ដងទៀត ៖\n$$f^{(n+1)}(x)=(-1)^nn!\\cdot\\left(-(n+1)\\right)x^{-n-2}=\\frac{(-1)^{n+1}(n+1)!}{x^{n+2}}$$\nរូបមន្តក៏ពិតចំពោះ $n+1$ ដែរ ។\nដូចនេះ $\\boxed{f'(x)=-\\frac{1}{x^2}}$ , $\\boxed{f''(x)=\\frac{2}{x^3}}$ , $\\boxed{f'''(x)=-\\frac{6}{x^4}}$ និង $\\boxed{f^{(n)}(x)=\\frac{(-1)^nn!}{x^{n+1}}}$ ។",
 "f'(x)=-\\frac{1}{x^2},\\ f''(x)=\\frac{2}{x^3},\\ f'''(x)=-\\frac{6}{x^4},\\ f^{(n)}(x)=\\frac{(-1)^nn!}{x^{n+1}}", [("diff(1/x,x,3)", "-6/x**4", "n=3"), ("diff(1/x,x,4)", "24/x**5", "n=4")])
row("nth_derivative", "hard",
 "រកដេរីវេលំដាប់ $n$ នៃ $f(x)=\\frac{1}{2x+1}$ ។",
 "ដំបូងគណនាពីរបីលំដាប់ ដើម្បីមើលលំនាំ ។ សរសេរ $f(x)=(2x+1)^{-1}$ ។\n$$f'(x)=-2(2x+1)^{-2}$$\n$$f''(x)=8(2x+1)^{-3}$$\n$$f'''(x)=-48(2x+1)^{-4}$$\nរាល់ពេលធ្វើដេរីវេ យើងគុណនឹងនិទស្សន្ត និងនឹង $2$ ដែលជាដេរីវេនៃកន្សោមខាងក្នុង ។ ដូច្នេះមេគុណគឺ $(-1)^n2^nn!$ ។\nដូចនេះ $\\boxed{f^{(n)}(x)=\\frac{(-1)^n2^nn!}{(2x+1)^{n+1}}}$ ។",
 "f^{(n)}(x)=\\frac{(-1)^n2^nn!}{(2x+1)^{n+1}}", [("diff(1/(2*x+1),x,3)", "-48/(2*x+1)**4", "n=3"), ("diff(1/(2*x+1),x,4)", "384/(2*x+1)**5", "n=4")])
row("nth_derivative", "medium",
 "គេឱ្យ $P(x)=x^4-2x^3+x-5$ ។ គណនាដេរីវេទី១ ដល់ទី៥ ។ តើអ្នកកត់សម្គាល់អ្វី ?",
 "ដេរីវេនីមួយៗបន្ថយដឺក្រេមួយ ។\n$$P'(x)=4x^3-6x^2+1$$\n$$P''(x)=12x^2-12x$$\n$$P'''(x)=24x-12$$\n$$P^{(4)}(x)=24$$\n$$P^{(5)}(x)=0$$\nពហុធាដឺក្រេ $4$ មានដេរីវេលំដាប់ $4$ ជាចំនួនថេរ ហើយចាប់ពីលំដាប់ $5$ ទៅ ដេរីវេស្មើសូន្យទាំងអស់ ។\nដូចនេះ $\\boxed{P'(x)=4x^3-6x^2+1}$ , $\\boxed{P''(x)=12x^2-12x}$ , $\\boxed{P'''(x)=24x-12}$ , $\\boxed{P^{(4)}(x)=24}$ និង $\\boxed{P^{(5)}(x)=0}$ ។",
 "P'(x)=4x^3-6x^2+1,\\ P''(x)=12x^2-12x,\\ P'''(x)=24x-12,\\ P^{(4)}(x)=24,\\ P^{(5)}(x)=0", [("diff(x**4-2*x**3+x-5,x,3)", "24*x-12", "third"), ("diff(x**4-2*x**3+x-5,x,4)", "24", "fourth"), ("diff(x**4-2*x**3+x-5,x,5)", "0", "fifth")])
row("approximation", "medium",
 "ដោយប្រើដេរីវេនៃ $f(x)=\\sqrt{x}$ ត្រង់ $x=100$ រកតម្លៃប្រហែលនៃ $\\sqrt{101}$ ។",
 "បើ $h$ តូច យើងមាន $f(a+h)\\approx f(a)+hf'(a)$ ព្រោះផលធៀបកំណើនខិតជិតដេរីវេ ។\nនៅទីនេះ $a=100$ , $h=1$ , $f(100)=10$ ហើយ $f'(x)=\\frac{1}{2\\sqrt{x}}$ ផ្ដល់ $f'(100)=\\frac{1}{20}$ ។\n$$\\sqrt{101}\\approx10+\\frac{1}{20}=10.05$$\nដូចនេះ $\\boxed{\\sqrt{101}\\approx10.05}$ ។",
 "\\sqrt{101}\\approx10.05", [("subs(diff(sqrt(x),x),x,100)", "Rational(1,20)", "slope"), ("10+subs(diff(sqrt(x),x),x,100)", "Rational(201,20)", "approximation")])
row("approximation", "medium",
 "គណនាតម្លៃប្រហែលនៃ $(1.02)^5$ ដោយប្រើដេរីវេនៃ $f(x)=x^5$ ត្រង់ $x=1$ ។",
 "យើងមាន $f(1)=1$ និង $f'(x)=5x^4$ នោះ $f'(1)=5$ ។\nដោយ $h=0.02$ តូច យើងប្រើការប៉ាន់ស្មាន $f(1+h)\\approx f(1)+hf'(1)$ ៖\n$$(1.02)^5\\approx1+0.02\\times5=1.1$$\nដូចនេះ $\\boxed{(1.02)^5\\approx1.1}$ ។",
 "(1.02)^5\\approx1.1", [("subs(diff(x**5,x),x,1)", "5", "slope"), ("1+Rational(1,50)*subs(diff(x**5,x),x,1)", "Rational(11,10)", "approximation")])
row("application_geometry", "medium",
 "កាំនៃរង្វង់មួយកើនឡើង ។ បង្ហាញថាដេរីវេនៃក្រឡាផ្ទៃ $S(r)=\\pi r^2$ ធៀបនឹង $r$ ស្មើនឹងបរិមាត្ររង្វង់ ។ គណនាតម្លៃនោះពេល $r=3$ ។",
 "តាមរូបមន្ត $(x^n)'=nx^{n-1}$ ដោយ $\\pi$ ជាចំនួនថេរ ៖ $$S'(r)=2\\pi r$$\nកន្សោម $2\\pi r$ គឺជាបរិមាត្ររង្វង់ដែលមានកាំ $r$ ។\nពេល $r=3$ គេបាន $S'(3)=6\\pi$ ។\nដូចនេះ $\\boxed{S'(r)=2\\pi r}$ និង $\\boxed{S'(3)=6\\pi}$ ។",
 "S'(3)=6\\pi", [("diff(pi*x**2,x)", "2*pi*x", "S'"), ("subs(diff(pi*x**2,x),x,3)", "6*pi", "value")])
row("application_geometry", "medium",
 "មាឌស្វ៊ែកាំ $r$ គឺ $V(r)=\\frac{4}{3}\\pi r^3$ ។ គណនា $V'(r)$ រួចប្រៀបធៀបជាមួយក្រឡាផ្ទៃស្វ៊ែ $4\\pi r^2$ ។",
 "ធ្វើដេរីវេធៀបនឹង $r$ ៖ $$V'(r)=\\frac{4}{3}\\pi\\cdot3r^2=4\\pi r^2$$\nលទ្ធផលនេះស្មើនឹងក្រឡាផ្ទៃស្វ៊ែ ។\nដូចនេះ $\\boxed{V'(r)=4\\pi r^2}$ ។",
 "V'(r)=4\\pi r^2", [("diff(Rational(4,3)*pi*x**3,x)", "4*pi*x**2", "V'")])
row("application_motion", "easy",
 "បាល់មួយត្រូវបានគេបោះឡើងលើ ហើយកម្ពស់របស់វាគិតជាម៉ែត្រគឺ $H(t)=20t-5t^2$ ។ រកល្បឿនពេល $t=1$ ។ តើនៅពេលណាបាល់ឈប់ឡើង ?",
 "ល្បឿនជាដេរីវេនៃកម្ពស់ ៖ $$H'(t)=20-10t$$\nពេល $t=1$ គេបាន $H'(1)=10$ ម៉ែត្រក្នុងមួយវិនាទី ។\nបាល់ឈប់ឡើង នៅពេលល្បឿនស្មើសូន្យ ៖ $20-10t=0$ នាំឱ្យ $t=2$ ។\nដូចនេះ $\\boxed{H'(1)=10}$ ហើយបាល់ឈប់ឡើងនៅខណៈ $\\boxed{t=2}$ វិនាទី ។",
 "H'(1)=10,\\ t=2", [("subs(diff(20*x-5*x**2,x),x,1)", "10", "speed"), ("subs(diff(20*x-5*x**2,x),x,2)", "0", "stop")])
row("application_cost", "medium",
 "ចំណាយលើការផលិត $x$ ឯកតាគឺ $C(x)=x^2+10x+50$ (គិតជាដុល្លារ) ។ គណនា $C'(20)$ ។ ប្រៀបធៀបជាមួយ $C(21)-C(20)$ ។",
 "ធ្វើដេរីវេ ៖ $C'(x)=2x+10$ ដូច្នេះ $C'(20)=50$ ។\nគណនាផលដកដោយផ្ទាល់ ៖ $C(21)=701$ និង $C(20)=650$ នាំឱ្យ $C(21)-C(20)=51$ ។\nតម្លៃទាំងពីរជិតគ្នា ព្រោះដេរីវេប្រាប់ការប្រែប្រួលប្រហែលនៃ $C$ ពេល $x$ កើនមួយឯកតា ។\nដូចនេះ $\\boxed{C'(20)=50}$ និង $\\boxed{C(21)-C(20)=51}$ ។",
 "C'(20)=50,\\ C(21)-C(20)=51", [("subs(diff(x**2+10*x+50,x),x,20)", "50", "C'"), ("subs(x**2+10*x+50,x,21)-subs(x**2+10*x+50,x,20)", "51", "difference")])
row("parameter_from_derivative", "hard",
 "រកចំនួនពិត $a$ និង $b$ ដើម្បីឱ្យពហុធា $P(x)=x^3+ax+b$ មានឫសឌុប $x=2$ ។",
 "ចំនួន $2$ ជាឫសឌុបលុះត្រាតែ $P(2)=0$ និង $P'(2)=0$ ។\nយើងមាន $P'(x)=3x^2+a$ ។ លក្ខខណ្ឌទី២ឱ្យ $12+a=0$ ដូច្នេះ $a=-12$ ។\nលក្ខខណ្ឌទី១ឱ្យ $8+2a+b=0$ ឬ $8-24+b=0$ នាំឱ្យ $b=16$ ។\nផ្ទៀងផ្ទាត់ ៖ $x^3-12x+16=(x-2)^2(x+4)$ ។\nដូចនេះ $\\boxed{a=-12,\\ b=16}$ ។",
 "a=-12,\\ b=16", [("subs(diff(x**3-12*x+16,x),x,2)", "0", "P'(2)"), ("subs(x**3-12*x+16,x,2)", "0", "P(2)"), ("x**3-12*x+16", "(x-2)**2*(x+4)", "factorisation")])
row("parameter_from_derivative", "hard",
 "រកចំនួនពិត $a,b$ ដើម្បីឱ្យអនុគមន៍ $f(x)=\\frac{ax+b}{x^2+1}$ ផ្ទៀងផ្ទាត់ $f(0)=1$ និង $f'(0)=3$ ។",
 "លក្ខខណ្ឌ $f(0)=1$ ឱ្យ $b=1$ ភ្លាម ។\nតាមរូបមន្តផលចែក ៖ $$f'(x)=\\frac{a(x^2+1)-2x(ax+b)}{(x^2+1)^2}$$\nត្រង់ $x=0$ ភាគយកនៅសល់ $a$ ហើយភាគបែងស្មើ $1$ ។ ដូច្នេះ $f'(0)=a=3$ ។\nដូចនេះ $\\boxed{a=3,\\ b=1}$ ។",
 "a=3,\\ b=1", [("subs((3*x+1)/(x**2+1),x,0)", "1", "f(0)"), ("subs(diff((3*x+1)/(x**2+1),x),x,0)", "3", "f'(0)")])
row("parameter_from_derivative", "hard",
 "គេឱ្យ $f(x)=x^2-4x+m$ និង $g(x)=\\frac{1}{x}$ ។ រក $m$ ដើម្បីឱ្យខ្សែកោងទាំងពីរមានចំណុចរួមត្រង់ $x=1$ ។ បន្ទាប់មកគណនាដេរីវេនៃផលគុណ $fg$ ត្រង់ $x=1$ ។",
 "ខ្សែកោងទាំងពីរកាត់គ្នាត្រង់ $x=1$ លុះត្រាតែ $f(1)=g(1)$ ។ នោះ $1-4+m=1$ ហើយ $m=4$ ។\nដូច្នេះ $f(x)=x^2-4x+4=(x-2)^2$ ។\nយើងមាន $f'(1)=-2$ , $g'(x)=-\\frac{1}{x^2}$ , $g'(1)=-1$ ។ តាមរូបមន្តផលគុណ ៖\n$$(fg)'(1)=f'(1)g(1)+f(1)g'(1)=(-2)(1)+(1)(-1)=-3$$\nដូចនេះ $\\boxed{m=4}$ និង $\\boxed{(fg)'(1)=-3}$ ។",
 "m=4,\\ (fg)'(1)=-3", [("subs(x**2-4*x+4,x,1)", "1", "f(1)=g(1)"), ("subs(diff((x-2)**2/x,x),x,1)", "-3", "product")])
row("even_odd", "hard",
 "បង្ហាញថា បើ $f$ ជាអនុគមន៍គូដែលមានដេរីវេ នោះ $f'$ ជាអនុគមន៍សេស ។ ផ្ទៀងផ្ទាត់ជាមួយ $f(x)=\\frac{1}{x^2+1}$ ។",
 "អនុគមន៍គូផ្ទៀងផ្ទាត់ $f(-x)=f(x)$ ។ ធ្វើដេរីវេលើអង្គទាំងពីរ ។ អង្គឆ្វេងជាអនុគមន៍បណ្ដាក់ ដែលកន្សោមខាងក្នុង $-x$ មានដេរីវេ $-1$ ៖\n$$-f'(-x)=f'(x)$$\nនេះមានន័យថា $f'(-x)=-f'(x)$ ពោលគឺ $f'$ ជាអនុគមន៍សេស ។\nផ្ទៀងផ្ទាត់ ៖ ចំពោះ $f(x)=\\frac{1}{x^2+1}$ គេបាន $f'(x)=-\\frac{2x}{(x^2+1)^2}$ ។ ជំនួស $-x$ ភាគបែងមិនប្រែ តែភាគយកប្ដូរសញ្ញា ។\nដូចនេះ $\\boxed{f'(-x)=-f'(x)}$ ។",
 "f'(-x)=-f'(x)", [("diff(1/(x**2+1),x)", "-2*x/(x**2+1)**2", "example")])
row("rules_abstract_uv", "medium",
 "គេឱ្យ $u$ ជាអនុគមន៍វិជ្ជមាន និងមានដេរីវេ ។ សរសេរដេរីវេនៃ $f=\\frac{1}{\\sqrt{u}}$ ជាអនុគមន៍នៃ $u$ និង $u'$ ។",
 "យើងសរសេរ $f=u^{-\\frac{1}{2}}$ ។ រូបមន្ត $(u^n)'=nu'u^{n-1}$ នៅតែប្រើបាន ជាមួយ $n=-\\frac{1}{2}$ ៖\n$$f'=-\\frac{1}{2}u'u^{-\\frac{3}{2}}$$\nសរសេរវិញជាឫសការេ ដោយ $u^{\\frac{3}{2}}=u\\sqrt{u}$ ។\nដូចនេះ $\\boxed{\\left(\\frac{1}{\\sqrt{u}}\\right)'=-\\frac{u'}{2u\\sqrt{u}}}$ ។",
 "\\left(\\frac{1}{\\sqrt{u}}\\right)'=-\\frac{u'}{2u\\sqrt{u}}", [("diff(1/sqrt(x**2+3),x)", "-2*x/(2*(x**2+3)*sqrt(x**2+3))", "instance u=x^2+3")])
row("composite_abstract", "medium",
 "គេឱ្យ $f(x)=x^2+1$ និង $g(x)=\\sqrt{x}$ ។ រកអនុគមន៍ $f\\circ g$ និង $g\\circ f$ រួចគណនាដេរីវេរបស់វា ។",
 "អនុគមន៍បណ្ដាក់ទី១ ៖ ចំពោះ $x\\geq0$ យើងមាន $(f\\circ g)(x)=(\\sqrt{x})^2+1=x+1$ ដូច្នេះដេរីវេស្មើ $1$ ។\nអនុគមន៍បណ្ដាក់ទី២ ៖ $(g\\circ f)(x)=\\sqrt{x^2+1}$ កំណត់លើ $IR$ ។ តាមរូបមន្តឫសការេ ៖\n$$(g\\circ f)'(x)=\\frac{2x}{2\\sqrt{x^2+1}}=\\frac{x}{\\sqrt{x^2+1}}$$\nឧទាហរណ៍នេះបង្ហាញថា លំដាប់នៃការបណ្ដាក់មានសារៈសំខាន់ ។\nដូចនេះ $\\boxed{(f\\circ g)'(x)=1}$ និង $\\boxed{(g\\circ f)'(x)=\\frac{x}{\\sqrt{x^2+1}}}$ ។",
 "(f\\circ g)'(x)=1,\\ (g\\circ f)'(x)=\\frac{x}{\\sqrt{x^2+1}}", [("diff(sqrt(x**2+1),x)", "x/sqrt(x**2+1)", "g∘f"), ("diff(x+1,x)", "1", "f∘g")])
row("composite_abstract", "hard",
 "អនុគមន៍ $f$ មានដេរីវេលើ $IR$ ហើយផ្ទៀងផ្ទាត់ $f(2x)=4f(x)$ ចំពោះគ្រប់ $x$ ។ បង្ហាញថា $f'(2x)=2f'(x)$ ។ រួចទាញរកតម្លៃ $f'(0)$ ។",
 "ធ្វើដេរីវេលើអង្គទាំងពីរនៃសមភាព ។ អង្គឆ្វេងជាអនុគមន៍បណ្ដាក់ ៖\n$$2f'(2x)=4f'(x)$$\nចែកនឹង $2$ គេបាន $f'(2x)=2f'(x)$ ។\nឥឡូវជំនួស $x=0$ ៖ $f'(0)=2f'(0)$ ដូច្នេះ $f'(0)=0$ ។\nដូចនេះ $\\boxed{f'(0)=0}$ ។ ឧទាហរណ៍ $f(x)=x^2$ ផ្ទៀងផ្ទាត់លក្ខខណ្ឌនេះ ។",
 "f'(0)=0", [("subs(diff(x**2,x),x,0)", "0", "example f=x^2"), ("subs(diff(x**2,x),x,6)-2*subs(diff(x**2,x),x,3)", "0", "example relation")])
row("piecewise_differentiability", "hard",
 "សិក្សាការមានដេរីវេត្រង់ $x=0$ នៃអនុគមន៍ $f(x)=x|x|$ ។ បង្ហាញថា $f'(x)=2|x|$ ។",
 "ដំបូងសរសេរដោយគ្មានតម្លៃដាច់ខាត ៖ $f(x)=x^2$ ពេល $x\\geq0$ ហើយ $f(x)=-x^2$ ពេល $x<0$ ។\nចំពោះ $x>0$ គេបាន $f'(x)=2x$ ហើយចំពោះ $x<0$ គេបាន $f'(x)=-2x$ ។\nត្រង់ $x=0$ ត្រូវប្រើនិយមន័យ ៖ $$\\lim_{x\\to0}\\frac{x|x|-0}{x}=\\lim_{x\\to0}|x|=0$$\nដូច្នេះ $f$ មានដេរីវេត្រង់ $x=0$ ហើយ $f'(0)=0$ ។\nដូចនេះ ចំពោះគ្រប់ $x$ យើងបាន $\\boxed{f'(x)=2|x|}$ ។",
 "f'(x)=2|x|", [("limit(x*Abs(x)/x,x,0)", "0", "at zero"), ("subs(diff(x**2,x),x,3)", "2*Abs(3)", "right branch"), ("subs(diff(-x**2,x),x,-3)", "2*Abs(-3)", "left branch")])
row("one_sided_derivative", "medium",
 "អនុគមន៍ $f(x)=\\left|x^2-4\\right|$ មានដេរីវេត្រង់ $x=2$ ឬទេ ? ពន្យល់ដោយគណនាដេរីវេខាងឆ្វេង និងខាងស្ដាំ ។",
 "ជិត $x=2$ យើងមាន $f(2)=0$ ។\nខាងស្ដាំ ៖ ពេល $x>2$ កន្សោម $x^2-4>0$ ដូច្នេះ $$\\lim_{x\\to2^+}\\frac{x^2-4}{x-2}=\\lim_{x\\to2^+}(x+2)=4$$\nខាងឆ្វេង ៖ ពេល $x<2$ ជិត $2$ កន្សោមនោះអវិជ្ជមាន ដូច្នេះ $$\\lim_{x\\to2^-}\\frac{-(x^2-4)}{x-2}=-4$$\nលីមីតទាំងពីរមិនស្មើគ្នា ។\nដូចនេះ $f$ គ្មានដេរីវេត្រង់ $x=2$ ទេ ដោយ $\\boxed{f'_+(2)=4\\neq f'_-(2)=-4}$ ។",
 "f'_+(2)=4,\\ f'_-(2)=-4", [("limit(Abs(x**2-4)/(x-2),x,2,'+')", "4", "right"), ("limit(Abs(x**2-4)/(x-2),x,2,'-')", "-4", "left")])
row("sum_of_mixed", "medium",
 "គណនាដេរីវេនៃ $y=\\left(x+\\frac{1}{x}\\right)^2$ ដោយមិនប្រើរូបមន្តអនុគមន៍បណ្ដាក់ ។",
 "យើងអាចពន្លាតការេ ព្រោះផលគុណ $x\\cdot\\frac{1}{x}=1$ ធ្វើឱ្យកន្សោមសាមញ្ញ ។ ចំពោះ $x\\neq0$ ៖\n$$y=x^2+2+\\frac{1}{x^2}=x^2+2+x^{-2}$$\nធ្វើដេរីវេតាមតួ ៖ $$y'=2x-2x^{-3}=2x-\\frac{2}{x^3}$$\nដូចនេះ $\\boxed{y'=2x-\\frac{2}{x^3}}$ ។",
 "y'=2x-\\frac{2}{x^3}", [("diff((x+1/x)**2,x)", "2*x-2/x**3", "derivative")])
row("sum_of_mixed", "medium",
 "រកដេរីវេនៃ $f(x)=\\sqrt{x}\\left(x^2-\\frac{1}{x}\\right)$ ចំពោះ $x>0$ ។",
 "កន្សោមនេះជាផលគុណ ប៉ុន្តែងាយស្រួលជាងបើយើងគុណចូលក្នុងវង់ក្រចក ហើយប្រើនិទស្សន្ត ៖\n$$f(x)=x^{\\frac{5}{2}}-x^{-\\frac{1}{2}}$$\nបន្ទាប់មកប្រើ $(x^n)'=nx^{n-1}$ ៖\n$$f'(x)=\\frac{5}{2}x^{\\frac{3}{2}}+\\frac{1}{2}x^{-\\frac{3}{2}}$$\nដោយ $x^{\\frac{3}{2}}=x\\sqrt{x}$ គេអាចសរសេរ ៖\nដូចនេះ $\\boxed{f'(x)=\\frac{5}{2}x\\sqrt{x}+\\frac{1}{2x\\sqrt{x}}}$ ។",
 "f'(x)=\\frac{5}{2}x\\sqrt{x}+\\frac{1}{2x\\sqrt{x}}", [("diff(sqrt(x)*(x**2-1/x),x)", "Rational(5,2)*x*sqrt(x)+1/(2*x*sqrt(x))", "derivative")])
row("implicit", "hard",
 "គេឱ្យ $x^2+xy+y^2=7$ ។ រក $y'$ ត្រង់ចំណុច $(1;2)$ ។",
 "ផ្ទៀងផ្ទាត់មុនថា ចំណុចនេះនៅលើខ្សែកោង ៖ $1+2+4=7$ ។\nធ្វើដេរីវេលើអង្គទាំងពីរ ដោយគិតថា $y$ ជាអនុគមន៍នៃ $x$ ។ តួ $xy$ ត្រូវប្រើរូបមន្តផលគុណ ៖\n$$2x+y+xy'+2yy'=0$$\nប្រមូលតួដែលមាន $y'$ ៖ $$(x+2y)y'=-(2x+y)$$\nត្រង់ $(1;2)$ ៖ $5y'=-4$ ។\nដូចនេះ $\\boxed{y'=-\\frac{4}{5}}$ ។",
 "y'=-\\frac{4}{5}", [("subs(diff((-x+sqrt(28-3*x**2))/2,x),x,1)", "Rational(-4,5)", "explicit branch")])
row("implicit", "hard",
 "បង្ហាញថា បើ $\\sqrt{x}+\\sqrt{y}=3$ ចំពោះ $x,y>0$ នោះ $y'=-\\sqrt{\\frac{y}{x}}$ ។ គណនា $y'$ ត្រង់ចំណុច $(1;4)$ ។",
 "ធ្វើដេរីវេលើអង្គទាំងពីរ ៖ $$\\frac{1}{2\\sqrt{x}}+\\frac{y'}{2\\sqrt{y}}=0$$\nគុណនឹង $2\\sqrt{y}$ ៖ $$y'=-\\frac{\\sqrt{y}}{\\sqrt{x}}=-\\sqrt{\\frac{y}{x}}$$\nត្រង់ $(1;4)$ គេបាន $y'=-\\sqrt{4}=-2$ ។\nដូចនេះ $\\boxed{y'=-2}$ ។",
 "y'=-2", [("subs(diff((3-sqrt(x))**2,x),x,1)", "-2", "explicit y=(3-sqrt x)^2")])
row("differential_relation", "bacii",
 "គេឱ្យ $f(x)=x\\sqrt{1+x^2}$ ។ ក. គណនា $f'(x)$ ។\nខ. បង្ហាញថា $(1+x^2)f'(x)-xf(x)... $ ជំនួសដោយ".replace("$(1+x^2)f'(x)-xf(x)... $ ជំនួសដោយ", "$(1+x^2)f'(x)=xf(x)+(1+x^2)\\sqrt{1+x^2}$ ។"),
 "ក. ដោយ $1+x^2>0$ ជានិច្ច នោះ $D=IR$ ។ តាមរូបមន្តផលគុណ ៖\n$$f'(x)=\\sqrt{1+x^2}+x\\cdot\\frac{x}{\\sqrt{1+x^2}}=\\frac{1+2x^2}{\\sqrt{1+x^2}}$$\nដូចនេះ $\\boxed{f'(x)=\\frac{1+2x^2}{\\sqrt{1+x^2}}}$ ។\nខ. មិនចាំបាច់ប្រើទម្រង់សម្រួលទេ ។ គុណទម្រង់ដំបូងនឹង $1+x^2$ ៖\n$$(1+x^2)f'(x)=(1+x^2)\\sqrt{1+x^2}+x\\cdot x\\sqrt{1+x^2}$$\nតួចុងក្រោយគឺ $x\\cdot f(x)$ ។\nដូចនេះ $\\boxed{(1+x^2)f'(x)=xf(x)+(1+x^2)\\sqrt{1+x^2}}$ ។",
 "f'(x)=\\frac{1+2x^2}{\\sqrt{1+x^2}},\\ (1+x^2)f'(x)=xf(x)+(1+x^2)\\sqrt{1+x^2}", [("diff(x*sqrt(1+x**2),x)", "(1+2*x**2)/sqrt(1+x**2)", "f'"), ("(1+x**2)*diff(x*sqrt(1+x**2),x)", "x*x*sqrt(1+x**2)+(1+x**2)*sqrt(1+x**2)", "relation")])
row("exam_style_multipart", "bacii",
 "គេឱ្យអនុគមន៍ $f(x)=\\frac{2x-1}{x+1}$ ។\nក. រកដែនកំណត់ $D$ នៃ $f$ ។\nខ. គណនា $f'(x)$ រួចទាញបញ្ជាក់ថា $f$ កើនលើចន្លោះនីមួយៗនៃ $D$ ។\nគ. រក $x$ ដែល $f'(x)=3$ ។",
 "ក. អនុគមន៍កំណត់លុះត្រាតែ $x+1\\neq0$ ។ ដូចនេះ $\\boxed{D=IR-\\{-1\\}}$ ។\nខ. តាមរូបមន្តផលចែក ៖ $$f'(x)=\\frac{2(x+1)-(2x-1)}{(x+1)^2}=\\frac{3}{(x+1)^2}$$\nដោយ $3>0$ និង $(x+1)^2>0$ លើ $D$ យើងបាន $f'(x)>0$ ជានិច្ច ។ ដូច្នេះ $\\boxed{f'(x)=\\frac{3}{(x+1)^2}}$ ហើយ $f$ កើនលើ $(-\\infty;-1)$ និងលើ $(-1;+\\infty)$ ។\nគ. សមីការ $\\frac{3}{(x+1)^2}=3$ សមមូលនឹង $(x+1)^2=1$ ។ ដូច្នេះ $x+1=1$ ឬ $x+1=-1$ ។\nដូចនេះ $\\boxed{x=0}$ ឬ $\\boxed{x=-2}$ ។",
 "D=IR-\\{-1\\},\\ f'(x)=\\frac{3}{(x+1)^2},\\ x=0,\\ x=-2", [("diff((2*x-1)/(x+1),x)", "3/(x+1)**2", "f'"), ("subs(diff((2*x-1)/(x+1),x),x,0)", "3", "x=0"), ("subs(diff((2*x-1)/(x+1),x),x,-2)", "3", "x=-2")])
row("exam_style_multipart", "bacii",
 "គេឱ្យ $f(x)=x\\sqrt{4-x}$ ។\nក. រកដែនកំណត់ ។\nខ. គណនា $f'(x)$ ចំពោះ $x<4$ ។\nគ. រកតម្លៃ $x$ ដែលធ្វើឱ្យ $f'(x)=0$ រួចគណនា $f$ ត្រង់តម្លៃនោះ ។",
 "ក. កន្សោមក្រោមឫសត្រូវ $4-x\\geq0$ ។ ដូចនេះ $\\boxed{D=(-\\infty;4]}$ ។\nខ. យក $u=x$ និង $v=\\sqrt{4-x}$ ។ យើងមាន $u'=1$ និង $v'=-\\frac{1}{2\\sqrt{4-x}}$ ។ រូបមន្តផលគុណឱ្យ ៖\n$$f'(x)=\\sqrt{4-x}-\\frac{x}{2\\sqrt{4-x}}=\\frac{2(4-x)-x}{2\\sqrt{4-x}}=\\frac{8-3x}{2\\sqrt{4-x}}$$\nដូចនេះ $\\boxed{f'(x)=\\frac{8-3x}{2\\sqrt{4-x}}}$ ។\nគ. ភាគយកស្មើសូន្យពេល $x=\\frac{8}{3}$ ដែលនៅក្នុង $D$ ។\n$$f\\left(\\frac{8}{3}\\right)=\\frac{8}{3}\\sqrt{\\frac{4}{3}}=\\frac{16}{3\\sqrt{3}}=\\frac{16\\sqrt{3}}{9}$$\nដូចនេះ $\\boxed{x=\\frac{8}{3}}$ និង $\\boxed{f\\left(\\frac{8}{3}\\right)=\\frac{16\\sqrt{3}}{9}}$ ។",
 "D=(-\\infty;4],\\ f'(x)=\\frac{8-3x}{2\\sqrt{4-x}},\\ x=\\frac{8}{3},\\ f\\left(\\frac{8}{3}\\right)=\\frac{16\\sqrt{3}}{9}", [("diff(x*sqrt(4-x),x)", "(8-3*x)/(2*sqrt(4-x))", "f'"), ("subs(diff(x*sqrt(4-x),x),x,Rational(8,3))", "0", "root"), ("subs(x*sqrt(4-x),x,Rational(8,3))", "16*sqrt(3)/9", "value")])
row("exam_style_multipart", "bacii",
 "គេឱ្យ $g(x)=\\frac{x^2+x+1}{x+1}$ ។\nក. សរសេរ $g(x)$ ជារាង $ax+b+\\frac{c}{x+1}$ ។\nខ. គណនា $g'(x)$ តាមពីររបៀប ។\nគ. គណនា $g'(1)$ ។",
 "ក. ចែកពហុធា ៖ $x^2+x+1=x(x+1)+1$ ដូច្នេះ ចំពោះ $x\\neq-1$ យើងបាន $\\boxed{g(x)=x+\\frac{1}{x+1}}$ គឺ $a=1$ , $b=0$ , $c=1$ ។\nខ. របៀបទី១ ៖ ពីរាងកាណូនិក $$g'(x)=1-\\frac{1}{(x+1)^2}=\\frac{x(x+2)}{(x+1)^2}$$\nរបៀបទី២ ៖ រូបមន្តផលចែក $$g'(x)=\\frac{(2x+1)(x+1)-(x^2+x+1)}{(x+1)^2}=\\frac{x^2+2x}{(x+1)^2}$$\nលទ្ធផលទាំងពីរដូចគ្នា ។\nគ. ជំនួស $x=1$ ៖ $g'(1)=\\frac{3}{4}$ ។\nដូចនេះ $\\boxed{g'(x)=\\frac{x(x+2)}{(x+1)^2}}$ និង $\\boxed{g'(1)=\\frac{3}{4}}$ ។",
 "g(x)=x+\\frac{1}{x+1},\\ g'(x)=\\frac{x(x+2)}{(x+1)^2},\\ g'(1)=\\frac{3}{4}", [("diff((x**2+x+1)/(x+1),x)", "x*(x+2)/(x+1)**2", "g'"), ("subs(diff((x**2+x+1)/(x+1),x),x,1)", "Rational(3,4)", "g'(1)")])
row("sum_identity", "hard",
 "ដោយធ្វើដេរីវេលើអង្គទាំងពីរនៃ $1+x+x^2+\\cdots+x^n=\\frac{x^{n+1}-1}{x-1}$ ($x\\neq1$) រកផលបូក $S=1+2x+3x^2+\\cdots+nx^{n-1}$ ។",
 "អង្គឆ្វេងជាពហុធា ហើយដេរីវេរបស់វាគឺ $S$ ដោយផ្ទាល់ ។\nអង្គស្ដាំជាផលចែក ដូច្នេះ ៖\n$$S=\\frac{(n+1)x^n(x-1)-(x^{n+1}-1)}{(x-1)^2}$$\nពន្លាតភាគយក ៖ $(n+1)x^{n+1}-(n+1)x^n-x^{n+1}+1=nx^{n+1}-(n+1)x^n+1$ ។\nដូចនេះ $\\boxed{S=\\frac{nx^{n+1}-(n+1)x^n+1}{(x-1)^2}}$ ។",
 "S=\\frac{nx^{n+1}-(n+1)x^n+1}{(x-1)^2}", [("diff(1+x+x**2+x**3,x)", "(3*x**4-4*x**3+1)/(x-1)**2", "instance n=3")])
row("derivative_at_point", "easy",
 "គេឱ្យ $f(x)=x^3$ ។ តើត្រង់ចំណុចណាខ្លះ ដែលដេរីវេស្មើនឹង $12$ ?",
 "ដេរីវេគឺ $f'(x)=3x^2$ ។\nយើងដោះស្រាយ $3x^2=12$ ឬ $x^2=4$ ។ សមីការនេះមានឫសពីរ គឺ $x=2$ និង $x=-2$ ។\nកូអរដោនេរបស់ចំណុចគឺ $(2;8)$ និង $(-2;-8)$ ។\nដូចនេះ ចំណុចដែលត្រូវរកគឺ $\\boxed{(2;8)}$ និង $\\boxed{(-2;-8)}$ ។",
 "(2;8),\\ (-2;-8)", [("subs(diff(x**3,x),x,2)", "12", "x=2"), ("subs(diff(x**3,x),x,-2)", "12", "x=-2")])
row("derivative_at_point", "medium",
 "គេឱ្យ $f(x)=x^2$ និង $g(x)=x^2-6x+k$ ។ រកចំនួនពិត $x$ ដែលដេរីវេនៃអនុគមន៍ទាំងពីរមានតម្លៃផ្ទុយគ្នា ។ តើលទ្ធផលអាស្រ័យនឹង $k$ ឬទេ ?",
 "យើងមាន $f'(x)=2x$ និង $g'(x)=2x-6$ ។ ចំនួនថេរ $k$ បាត់ក្នុងការធ្វើដេរីវេ ដូច្នេះលទ្ធផលមិនអាស្រ័យនឹង $k$ ទេ ។\nលក្ខខណ្ឌគឺ $f'(x)+g'(x)=0$ ៖ $$2x+2x-6=0$$\nគេបាន $x=\\frac{3}{2}$ ។\nដូចនេះ $\\boxed{x=\\frac{3}{2}}$ ។",
 "x=\\frac{3}{2}", [("subs(diff(x**2,x)+diff(x**2-6*x+5,x),x,Rational(3,2))", "0", "condition with k=5")])

